 20	json workspace_json(const Workspace::WorkspaceSnapshot& workspace)
 21	{
 22	    json plates = json::array();
 23	    for (const auto& plate : workspace.plates) {
 24	        json objects = json::array();
 25	        for (const auto& object : plate.objects)
 26	            objects.push_back(json{{"id", std::to_string(object.id.value())}, {"name", object.name},
 27	                                   {"instances", object.instances.size()}});
 28	        plates.push_back(json{{"id", std::to_string(plate.id.value())}, {"name", plate.name},
 29	                              {"active", plate.active}, {"sliced", plate.sliced}, {"objects", std::move(objects)}});
 30	    }
 31	    json selected = json::array();
 32	    for (const auto id : workspace.selected_objects)
 33	        selected.push_back(std::to_string(id.value()));
 34	    return json{{"sessionId", std::to_string(workspace.session.value())},
