 43	bool available_in_app(const ToolDefinition& definition, bool allow_import, const std::vector<std::string>& session_tools)
 44	{
 45	    // A session with a subject of its own offers exactly the tools it names,
 46	    // and those may be its own rather than the app's.
 47	    if (!session_tools.empty())
 48	        return std::find(session_tools.begin(), session_tools.end(), definition.name) != session_tools.end() &&
 49	               (has_exposure(definition.exposure, ToolExposure::InApp) || has_exposure(definition.exposure, ToolExposure::Printer));
 50	    return has_exposure(definition.exposure, ToolExposure::InApp) &&
 51	           (definition.availability == ToolAvailability::Always || allow_import);
 52	}
