 54	bool has_closed_required_objects(const json& schema)
 55	{
 56	    if (schema.value("type", json()) == "object") {
 57	        if (schema.value("additionalProperties", json()) != false)
 58	            return false;
 59	        const auto properties = schema.value("properties", json::object());
 60	        const auto required = schema.value("required", json::array());
 61	        for (const auto& property : properties.items())
 62	            if (std::find(required.begin(), required.end(), property.key()) == required.end() ||
 63	                !has_closed_required_objects(property.value()))
 64	                return false;
 65	    }
 66	    return !schema.contains("items") || has_closed_required_objects(schema["items"]);
 67	}
