110	json tools_for(ToolSearch search, const std::vector<std::string>& session_tools)
111	{
112	    json tools = json::array();
113	    json namespaces = json::object();
114	    for (const ToolDefinition& definition : ToolRegistry::instance().definitions()) {
115	        // Availability still gates execution. Advertising import consistently
116	        // avoids changing the cached tools prefix when an attachment is added.
117	        if (!available_in_app(definition, true, session_tools))
118	            continue;
119	        json tool{{"type", "function"},
120	                             {"name", definition.name},
121	                             {"description", definition.description},
122	                             // OpenAI strict mode cannot express optional
123	                             // fields or dynamic maps. Preserve the registry
124	                             // schema; native validation still owns acceptance.
125	                             {"strict", has_closed_required_objects(definition.input_schema)},
126	                             {"parameters", definition.input_schema}};
127	        const auto* set = deferred_toolset(definition.handler);
128	        if (search != ToolSearch::None && set != nullptr)
129	            tool["defer_loading"] = true;
130	        if (search == ToolSearch::Namespaces && set != nullptr) {
131	            if (!namespaces.contains(set->name))
132	                namespaces[set->name] = json{{"type", "namespace"}, {"name", set->name},
133	                                            {"description", set->description}, {"tools", json::array()}};
134	            namespaces[set->name]["tools"].push_back(std::move(tool));
135	        } else {
136	            tools.push_back(std::move(tool));
137	        }
138	    }
139	    for (const auto& entry : namespaces.items())
140	        tools.push_back(entry.value());
141	    if (search != ToolSearch::None)
142	        tools.push_back(json{{"type", "tool_search"}});
143	    return tools;
144	}
