181	json OpenAIResponsesAgent::initial_input(const AgentRequest& request) const
182	{
183	    json input = json::array();
184	    for (const auto& message : request.conversation) {
185	        if (message.call_id.empty()) {
186	            input.push_back(json{{"role", message.role}, {"content", message.text}});
187	            continue;
188	        }
189	        // A call from an earlier turn, replayed for this stateless request.
190	        // Its call_id pairs it with its output. The item id the service gave
191	        // the call is not sent: with store:false it names nothing kept.
192	        json call{{"type", "function_call"}, {"call_id", message.call_id}, {"name", message.tool},
193	                  {"arguments", message.arguments_json}};
194	        if (!m_title_request && m_session.tool_names.empty() && m_config.tool_search == ToolSearch::Namespaces) {
195	            const auto* definition = ToolRegistry::instance().find(message.tool);
196	            const auto* set = definition == nullptr ? nullptr : deferred_toolset(definition->handler);
197	            if (set != nullptr)
198	                call["namespace"] = set->name;
199	        }
200	        input.push_back(std::move(call));
201	        input.push_back(json{{"type", "function_call_output"}, {"call_id", message.call_id}, {"output", message.output_json}});
202	    }
203	    if (request.purpose == AgentRequest::Purpose::ConversationTitle)
204	        return input;
205	    // A turn the app started, after one of its own notes: nothing was said,
206	    // and an empty user message would read as the person saying nothing.
207	    if (request.user_text.empty() && request.attachments.empty() && !request.session.include_workspace)
208	        return input;
209	
210	    json content = json::array();
211	    std::ostringstream context;
212	    context << request.user_text;
213	    if (request.session.include_workspace)
214	        context << "\n\nAuthoritative JusPrin workspace context:\n" << workspace_json(request.workspace).dump();
215	    for (const auto& attachment : request.attachments) {
216	        context << "\nAttachment " << attachment.id << ": " << attachment.name << " [" << attachment.kind << "]";
217	        if (!attachment.summary.empty())
218	            context << " — " << attachment.summary;
219	        if (!attachment.text.empty())
220	            context << "\n<attachment id=\"" << attachment.id << "\">\n" << attachment.text << "\n</attachment>";
221	    }
222	    content.push_back(json{{"type", "input_text"}, {"text", context.str()}});
223	    for (const auto& attachment : request.attachments) {
224	        if (attachment.bytes.empty())
225	            continue;
226	        const std::string mime = attachment.mime.empty() ? "application/octet-stream" : attachment.mime;
227	        const std::string data_url = "data:" + mime + ";base64," + base64_encode(attachment.bytes);
228	        if (attachment.kind == "image")
229	            content.push_back(json{{"type", "input_image"}, {"image_url", data_url}});
230	        else if (attachment.kind == "pdf")
231	            content.push_back(json{{"type", "input_file"}, {"filename", attachment.name}, {"file_data", data_url}});
232	    }
233	    input.push_back(json{{"role", "user"}, {"content", std::move(content)}});
234	    return input;
235	}
