281	bool OpenAIResponsesAgent::continue_after_tool(const AgentToolResult& result)
282	{
283	    if (!m_busy || !m_waiting_for_tool || result.call_id != m_pending_call_id)
284	        return false;
285	    m_call_outputs.push_back(json{{"type", "function_call_output"}, {"call_id", result.call_id}, {"output", result.output_json}});
286	    // A function result is text only; the picture follows the outputs as an image input.
287	    if (result.image)
288	        m_call_images.push_back(json{{"role", "user"},
289	                                     {"content", json::array({json{{"type", "input_text"}, {"text", "The image returned by call " + result.call_id + "."}},
290	                                                              json{{"type", "input_image"},
291	                                                                   {"image_url", "data:" + result.image->mime_type + ";base64," + result.image->base64}}})}});
292	    if (result.state != tool_state_name(ToolState::Succeeded))
293	        m_call_failed = true;
294	    m_waiting_for_tool = false;
295	    m_pending_call_id.clear();
296	    return answer_calls();
297	}
