307	// Runs the response's next call, or sends every answer once none is left. The
308	// model made its later calls before it could see an earlier one fail, so after
309	// a failure the calls that would change the project are not run: the model
310	// gets the failure and decides again. A read changes nothing and still runs.
311	bool OpenAIResponsesAgent::answer_calls()
312	{
313	    while (!m_calls.empty()) {
314	        ResponseCall next = std::move(m_calls.front());
315	        m_calls.pop_front();
316	        if (next.refusal.is_null() && m_call_failed && next.changes_project)
317	            next.refusal = json{{"state", "failed"},
318	                                {"error", {{"code", "not_run"},
319	                                           {"message", "Not run: an earlier call in the same response failed. Read its result and decide again."}}}};
320	        if (!next.refusal.is_null()) {
321	            m_call_outputs.push_back(json{{"type", "function_call_output"}, {"call_id", next.call.call_id}, {"output", next.refusal.dump()}});
322	            m_call_failed = true;
323	            continue;
324	        }
325	        m_pending_call_id  = next.call.call_id;
326	        m_waiting_for_tool = true;
327	        m_events.push_back(AgentEvent::tool_call(std::move(next.call)));
328	        return true;
329	    }
330	    json input = m_input_history;
331	    input.insert(input.end(), m_call_outputs.begin(), m_call_outputs.end());
332	    input.insert(input.end(), m_call_images.begin(), m_call_images.end());
333	    m_call_outputs = json::array();
334	    m_call_images  = json::array();
335	    m_call_failed  = false;
336	    return post(std::move(input));
337	}
