339	bool OpenAIResponsesAgent::post(json input)
340	{
341	    m_sse_buffer.clear();
342	    m_terminal_seen = false;
343	    m_busy = true;
344	    AgentHttpRequest request;
345	    request.url = m_config.endpoint;
346	    request.authorization = "Bearer " + m_config.api_key;
347	    request.idempotency_key = m_request_id + "-request-" + std::to_string(++m_request_sequence);
348	    // store:false requests are stateless. Retain the complete turn input,
349	    // including user context and earlier tool results, for each continuation.
350	    m_input_history = input;
351	    request.body = request_body(std::move(input)).dump();
352	    const std::uint64_t generation = ++m_http_generation;
353	    if (!m_transport->post(std::move(request), [this, generation](AgentHttpEvent event) {
354	            accept_http(generation, std::move(event));
355	        })) {
356	        m_busy = false;
357	        return false;
358	    }
359	    return true;
360	}
