368	void OpenAIResponsesAgent::parse_sse_frame(const std::string& frame)
369	{
370	    std::string payload;
371	    std::istringstream lines(frame);
372	    std::string line;
373	    while (std::getline(lines, line)) {
374	        if (!line.empty() && line.back() == '\r')
375	            line.pop_back();
376	        if (line.rfind("data:", 0) == 0) {
377	            std::string part = line.substr(5);
378	            if (!part.empty() && part.front() == ' ')
379	                part.erase(part.begin());
380	            if (!payload.empty())
381	                payload += '\n';
382	            payload += part;
383	        }
384	    }
385	    if (payload.empty() || payload == "[DONE]")
386	        return;
387	    const json event = json::parse(payload, nullptr, false);
388	    if (!event.is_object()) {
389	        fail(AgentError{"malformed_response", "The Agent service returned an unreadable streaming response.", false});
390	        return;
391	    }
392	    const std::string type = event.value("type", "");
393	    if (type == "response.output_text.delta" && event.contains("delta") && event["delta"].is_string())
394	        m_events.push_back(AgentEvent::delta(event["delta"].get<std::string>()));
395	    else if (type == "response.completed" && event.contains("response"))
396	        finish_response(event["response"]);
397	    else if (type == "response.incomplete")
398	        fail(AgentError{"incomplete_response", "The Agent service stopped before finishing its response.", true});
399	    else if (type == "response.failed" || type == "error")
400	        fail(AgentError{"agent_service_error", "The Agent service could not complete the response.", true});
401	}
