403	void OpenAIResponsesAgent::finish_response(const json& response)
404	{
405	    if (m_terminal_seen)
406	        return;
407	    m_terminal_seen = true;
408	    if (!response.is_object() || !response.contains("output") || !response["output"].is_array()) {
409	        fail(AgentError{"malformed_response", "The Agent service response did not contain valid output.", false});
410	        return;
411	    }
412	    const auto& output = response["output"];
413	    m_input_history.insert(m_input_history.end(), output.begin(), output.end());
414	    if (m_config.usage_listener && response.contains("usage") && response["usage"].is_object()) {
415	        const json& usage = response["usage"];
416	        AgentUsage   reported;
417	        reported.input  = usage.value("input_tokens", std::uint64_t{0});
418	        reported.output = usage.value("output_tokens", std::uint64_t{0});
419	        reported.total  = usage.value("total_tokens", std::uint64_t{0});
420	        if (usage.contains("input_tokens_details") && usage["input_tokens_details"].is_object())
421	            reported.cached_input = usage["input_tokens_details"].value("cached_tokens", std::uint64_t{0});
422	        m_config.usage_listener(reported);
423	    }
424	    for (const json& item : output) {
425	        if (!item.is_object() || item.value("type", "") != "function_call")
426	            continue;
427	        const std::string call_id = item.value("call_id", "");
428	        ToolRequest request{item.value("name", ""), item.value("arguments", "{}")};
429	        const ToolDefinition* definition = ToolRegistry::instance().find(request.tool);
430	        const bool available = !m_title_request && definition != nullptr && available_in_app(*definition, m_allow_import, m_session.tool_names);
431	        ToolValidationResult validation;
432	        if (available)
433	            validation = ToolRegistry::instance().validate_call(*definition, request.arguments_json);
434	        // A call to no tool of this turn, or with arguments that miss the
435	        // tool's contract, never reaches a card. The model gets the refusal as
436	        // that call's result and may correct it, a bounded number of times
437	        // per turn.
438	        constexpr unsigned kRejectedCallLimit = 2;
439	        const bool refused = !available || !validation.valid();
440	        if (refused && m_config.refusal_listener)
441	            m_config.refusal_listener(request.tool, request.arguments_json, available ? validation.error->code : "unknown_tool");
442	        if (call_id.empty() || (refused && (m_title_request || m_rejected_calls >= kRejectedCallLimit))) {
443	            fail(AgentError{"malformed_tool_call", "The Agent returned an invalid tool call.", false});
444	            return;
445	        }
446	        ResponseCall next;
447	        if (refused) {
448	            ++m_rejected_calls;
449	            // A deferred tool's parameters reach the model only when tool
450	            // search returns the tool, so that is where to send it for them.
451	            const bool searchable = m_session.tool_names.empty() && m_config.tool_search != ToolSearch::None;
452	            const bool hidden     = searchable && definition != nullptr && deferred_toolset(definition->handler) != nullptr;
453	            json error = available ?
454	                json{{"code", validation.error->code},
455	                     {"message", validation.error->message +
456	                                     (hidden ? " Nothing was queued. This tool's parameters arrive when tool search returns it: "
457	                                               "search for it by name, then call it again with those parameters." :
458	                                               " Nothing was queued. Check the arguments against this tool's parameters and call it again.")}} :
459	                json{{"code", "unknown_tool"},
460	                     {"message", "There is no tool named \"" + request.tool + "\" here. Nothing was queued. " +
461	                                     (searchable ? "Use one of the listed tools, or find the right one with tool search." :
462	                                                   "Use one of the listed tools.")}};
463	            next.call.call_id = call_id;
464	            next.refusal      = json{{"state", "failed"}, {"error", std::move(error)}};
465	        } else {
466	            request.arguments_json = std::move(validation.arguments_json);
467	            next.changes_project   = definition->action_class != ActionClass::ReadOnly;
468	            next.call              = AgentToolCall{call_id, std::move(request), true};
469	        }
470	        m_calls.push_back(std::move(next));
471	    }
472	    if (m_calls.empty()) {
473	        m_busy = false;
474	        m_events.push_back(AgentEvent::completed());
475	        return;
476	    }
477	    if (!answer_calls())
478	        fail(AgentError{"agent_continuation_failed", "The Agent could not be given its tool results.", true});
479	}
