# Runs one arm of one experiment: each scenario -Runs times, one harness at a time.
#   run.ps1 -Experiment blind-calls -Arm search-first -File C:\...\exp\blind-calls\search-first.json
#   run.ps1 -Experiment blind-calls -Arm control                      (no -File: the control, unchanged)
# Records land in exp\<Experiment>\<Arm>\<scenario>-<n>.json beside a .log. A run whose record exists is skipped,
# so an interrupted arm can be started again. When the arm ends, <Arm>\_status.txt says how.
param(
    [Parameter(Mandatory)][string]$Experiment,
    [Parameter(Mandatory)][string]$Arm,
    [string]$File = '',
    [int]$Runs = 3,
    [string[]]$Scenarios = @('petg-question', 'what-is-this', 'desk-ornament', 'outdoor-fitting'),
    [string]$ScenarioDir = 'C:\src\JusPrin\tests\project_journey\scenarios',
    [double]$BudgetUsd = 0.90,
    [string]$Exe = "shell_integration_harness_exp.exe"
)
$exe = Join-Path 'C:\src\JusPrin\build\tests\shell\Release' $Exe
$root = Join-Path $PSScriptRoot $Experiment
$out = Join-Path $root $Arm
$status = Join-Path $out '_status.txt'
New-Item -ItemType Directory -Force $out | Out-Null
Remove-Item $status -ErrorAction SilentlyContinue
function Finish([string]$message, [int]$code) { Set-Content $status $message; $message; exit $code }
if ($File -and -not (Test-Path $File)) { Finish "STOPPED: no experiment file at $File" 2 }

# List price for deepseek/deepseek-v4-flash on OpenRouter, with no discount for cached input, so this overstates.
function Spent {
    $in = 0; $outTokens = 0
    Get-ChildItem $root -Recurse -Filter *.log -ErrorAction SilentlyContinue | ForEach-Object {
        Select-String -Path $_.FullName -Pattern 'LIVE USAGE .*input_tokens=(\d+) cached_input_tokens=\d+ output_tokens=(\d+)' | ForEach-Object {
            $in += [int64]$_.Matches[0].Groups[1].Value; $outTokens += [int64]$_.Matches[0].Groups[2].Value
        }
    }
    [pscustomobject]@{ Input = $in; Output = $outTokens; Usd = [math]::Round($in * 0.091 / 1e6 + $outTokens * 0.182 / 1e6, 3) }
}

