// OpenRouter serves an open-weight model from many hosts, and they render the
// app's developer messages differently (tests/printer_prompt/README.md, "Which
// model"). The adapter sends no routing, so a journey adds the prompt tests'
// own hosts to each request here.
class PinnedHosts final : public Agent::IAgentHttpTransport
{
public:
    static inline const std::vector<std::string> kHosts{"Alibaba", "Novita", "Baidu", "AtlasCloud"};

    explicit PinnedHosts(std::unique_ptr<Agent::IAgentHttpTransport> inner) : m_inner(std::move(inner)) {}

    bool post(Agent::AgentHttpRequest request, EventFn event) override
    {
        nlohmann::json body = nlohmann::json::parse(request.body);
        body["provider"]    = {{"order", kHosts}, {"allow_fallbacks", false}};
        // A chat's title is asked for without tools and is no part of an experiment.
        if (body.contains("tools") && !apply_experiment(body))
            return false;
        // This model reads text only, and OpenRouter refuses a request that
        // holds a picture, which would end the turn on the model's choice to
        // look. The picture is withheld and the model told so, to see what it
        // does next; what it would have made of the picture stays unknown.
        if (body.contains("input") && body["input"].is_array())
            for (auto& item : body["input"])
                if (item.is_object() && item.contains("content") && item["content"].is_array())
                    for (auto& part : item["content"])
                        if (part.is_object() && part.value("type", "") == "input_image") {
                            part = {{"type", "input_text"}, {"text", "[The picture is not shown: this model cannot view pictures.]"}};
                            g_journey_route["picturesWithheld"] = true;
                        }
        request.body = body.dump();
        return m_inner->post(std::move(request), std::move(event));
    }

    // --journey-experiment: the instructions, tool descriptions and tool
    // loading one run is to try, changed in the request itself so a wording
    // can be tried without building it in. What was sent goes in the record.
    static bool apply_experiment(nlohmann::json& body)
    {
        const nlohmann::json& experiment = g_journey_experiment;
        const auto refuse = [](const std::string& why) {
            g_journey_experiment_error = why;
            std::cerr << "HARNESS ERROR journey experiment: " << why << '\n';
            return false;
        };
        std::string instructions = body.value("instructions", std::string());
        if (experiment.contains("instructions"))
            instructions = experiment["instructions"].get<std::string>();
        for (const auto& edit : experiment.value("replace", nlohmann::json::array())) {
            const std::string find = edit.at("find").get<std::string>();
            const auto        at   = instructions.find(find);
            // An edit that changes nothing would run the control and call it the experiment.
            if (find.empty() || at == std::string::npos || instructions.find(find, at + 1) != std::string::npos)
                return refuse("\"" + find.substr(0, 60) + "\" is not in the instructions exactly once");
            instructions.replace(at, find.size(), edit.at("with").get<std::string>());
        }
        body["instructions"] = instructions;
        const auto descriptions = experiment.value("toolDescriptions", nlohmann::json::object());
        const auto loaded       = experiment.value("loaded", std::vector<std::string>{});
        std::set<std::string> unseen;
        for (const auto& entry : descriptions.items()) unseen.insert(entry.key());
        unseen.insert(loaded.begin(), loaded.end());
        nlohmann::json sent = nlohmann::json::array();
        for (auto& tool : body["tools"]) {
            if (tool.value("type", "") != "function")
                continue;
            const std::string name = tool.value("name", "");
            unseen.erase(name);
            if (descriptions.contains(name))
                tool["description"] = descriptions[name];
            if (std::find(loaded.begin(), loaded.end(), name) != loaded.end())
                tool.erase("defer_loading");
            sent.push_back({{"name", name}, {"deferred", tool.value("defer_loading", false)}, {"description", tool.value("description", "")}});
        }
        if (!unseen.empty())
            return refuse("no tool named " + *unseen.begin());
        if (!g_journey_route.contains("sent"))
            g_journey_route["sent"] = {{"experiment", experiment.value("name", "")}, {"instructions", instructions}, {"tools", std::move(sent)}};
        return true;
    }

    void cancel() override { m_inner->cancel(); }

private:
    std::unique_ptr<Agent::IAgentHttpTransport> m_inner;
};

// The app ships no stand-in Agent, so each mode's Agent is installed here
// through the host's own set_agent, the call setup uses when a key verifies.
void install_harness_agent(HarnessState::Mode mode)
{
