// Count tool calls by tool across journey records, and first-request input tokens.
//   node toolcounts.mjs <arm dir> [<arm dir> ...]
import fs from 'node:fs';
import path from 'node:path';
const counts = {};
let runs = 0, firstInputs = [], totalInput = 0, totalCached = 0, totalOutput = 0, requests = 0;
for (const dir of process.argv.slice(2)) {
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json') && !f.startsWith('_')).sort()) {
    let r;
    try { r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8')); } catch { continue; }
    if (!r.turns) continue;
    runs++;
    for (const t of r.turns) for (const c of t.calls ?? []) counts[c.tool] = (counts[c.tool] ?? 0) + 1;
    for (const c of r.refusedCalls ?? []) counts[c.tool + ' (refused)'] = (counts[c.tool + ' (refused)'] ?? 0) + 1;
    const first = r.turns[0]?.requests?.[0] ?? r.turns[1]?.requests?.[0];
    if (first) firstInputs.push(first.inputTokens);
    if (r.usage) { totalInput += r.usage.inputTokens; totalCached += r.usage.cachedInputTokens; totalOutput += r.usage.outputTokens; requests += r.usage.requests; }
  }
}
console.log(`runs=${runs} requests=${requests} input=${totalInput} cached=${totalCached} output=${totalOutput}`);
console.log(`first request input tokens: ${firstInputs.join(', ')}`);
for (const [tool, n] of Object.entries(counts).sort((a, b) => b[1] - a[1])) console.log(`${String(n).padStart(4)}  ${tool}`);

