// The mechanism behind the loaded set. On OpenRouter a deferred function is
// hidden until a search returns it; on OpenAI its name and description show
// but its parameters do not, and inside a namespace nothing of it shows. A
// tool the model is told about by name it calls by name, so without the
// parameters it guesses them and is refused (tests/project_journey/README.md,
// 2026-10-13: 20 of 25 refusals in 12 runs). Every tool the instructions name,
// and every tool a loaded tool's description names, is therefore loaded.
TEST_CASE("every tool the instructions name is loaded", "[agent][openai][tools][loading]")
{
    OpenAIResponsesConfig config{"key"};
    config.tool_search = GENERATE(ToolSearch::Functions, ToolSearch::Namespaces);
    auto transport = std::make_unique<FakeTransport>();
    auto* fake = transport.get();
    OpenAIResponsesAgent agent(config, std::move(transport));
    REQUIRE(agent.start(request_fixture()));
    const json body = json::parse(fake->requests.back().body);
    std::set<std::string> loaded;
    for (const auto& tool : body["tools"])
        if (tool["type"] == "function" && !tool.contains("defer_loading"))
            loaded.insert(tool["name"].get<std::string>());
    REQUIRE_FALSE(loaded.empty());
    // Every snake_case word of a text that is a tool's name.
    const auto tools_named_in = [](const std::string& text) {
        std::set<std::string> names;
        std::size_t at = 0;
        while (at < text.size()) {
            const std::size_t end = text.find_first_not_of("REDACTED", at);
            const std::string word = text.substr(at, (end == std::string::npos ? text.size() : end) - at);
            if (word.find('_') != std::string::npos && ToolRegistry::instance().find(word) != nullptr)
                names.insert(word);
            at = end == std::string::npos ? text.size() : end + 1;
        }
        return names;
    };
    std::set<std::string> named = tools_named_in(body["instructions"].get<std::string>());
    CHECK(named.count("intent_update") == 1); // the scan reads the real text
    for (const auto& tool : body["tools"])
        if (tool["type"] == "function" && loaded.count(tool["name"].get<std::string>()) == 1) {
            const auto more = tools_named_in(tool["description"].get<std::string>());
            named.insert(more.begin(), more.end());
        }
    for (const std::string& name : named) {
        CAPTURE(name);
        CHECK(loaded.count(name) == 1);
    }
}

