// How often a deferred tool, found by search in one user turn, was searched for again in a later turn of the
// same run (the app replays its own call history without the provider's search items, so a found tool is
// not kept loaded). Reads the harness logs: each model response is one "JUSPRIN LIVE REQUEST items=..." line,
// and a turn ends at a "journey_turn_N_ended" or "journey_opening_message" check line.
//   node repeats.mjs <arm dir> [<arm dir> ...]
import fs from 'node:fs';
import path from 'node:path';
let searches = 0, repeatSearches = 0, runs = 0, searchesPerRun = [];
const loaded = new Set(['workspace_inspect', 'settings_search', 'settings_get']);
for (const dir of process.argv.slice(2)) {
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.log')).sort()) {
    const lines = fs.readFileSync(path.join(dir, file), 'utf8').split('\n');
    runs++;
    let turn = 0, runSearches = 0;
    const foundInTurn = {}; // tool -> first turn in which a search preceded a call to it
    for (const line of lines) {
      if (/journey_turn_\d+_ended|journey_opening_message/.test(line)) { turn++; continue; }
      const m = line.match(/JUSPRIN LIVE REQUEST .*items=(.*)$/);
      if (!m) continue;
      const items = m[1].split(',').map(s => s.trim());
      let pendingSearches = 0;
      for (const item of items) {
        if (item === 'openrouter:tool_search' || item === 'tool_search_call') { pendingSearches++; searches++; runSearches++; continue; }
        const call = item.match(/^function_call:\/?(.+)$/);
        if (!call) continue;
        const tool = call[1];
        if (loaded.has(tool)) continue;
        if (pendingSearches > 0) {
          if (tool in foundInTurn && foundInTurn[tool] < turn) repeatSearches += pendingSearches;
          if (!(tool in foundInTurn)) foundInTurn[tool] = turn;
          pendingSearches = 0;
        }
      }
    }
    searchesPerRun.push(`${file.replace('.log', '')}:${runSearches}`);
  }
}
console.log(`runs=${runs} searches=${searches} of which repeats of a tool already found in an earlier turn of the same run=${repeatSearches}`);
console.log(searchesPerRun.join('  '));

