// and a turn ends at a "HARNESS CHECK journey_turn_N_ended" or "journey_opening_message" line.
//   node repeats.mjs <arm dir> [<arm dir> ...]
import fs from 'node:fs';
import path from 'node:path';
let searches = 0, repeatSearches = 0, runs = 0, searchesPerRun = [], repeatedTools = {};
const loaded = new Set(['workspace_inspect', 'settings_search', 'settings_get']);
for (const dir of process.argv.slice(2)) {
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.log')).sort()) {
    const lines = fs.readFileSync(path.join(dir, file), 'utf8').split('\n').map(l => l.replace(/\r$/, ''));
    runs++;
    let turn = 0, runSearches = 0;
    const foundInTurn = {}; // tool -> first turn in which a search preceded a call to it
    for (const line of lines) {
