      const at = line.indexOf('JUSPRIN LIVE REQUEST');
      if (at < 0) continue;
      const itemsAt = line.indexOf('items=');
      if (itemsAt < 0) continue;
      const items = line.slice(itemsAt + 6).split(',').map(s => s.trim());
      let pendingSearches = 0;
      for (const item of items) {
        if (item === 'openrouter:tool_search' || item === 'tool_search_call') { pendingSearches++; searches++; runSearches++; continue; }
        if (!item.startsWith('function_call:')) continue;
        const tool = item.replace(/^function_call:\/?/, '');
        if (loaded.has(tool)) continue;
        if (pendingSearches > 0) {
          if (tool in foundInTurn && foundInTurn[tool] < turn) { repeatSearches += pendingSearches; repeatedTools[tool] = (repeatedTools[tool] ?? 0) + 1; }
          if (!(tool in foundInTurn)) foundInTurn[tool] = turn;
          pendingSearches = 0;
        }
      }
    }
    searchesPerRun.push(`${file.replace('.log', '')}:${runSearches}`);
  }
}
console.log(`runs=${runs} searches=${searches}; searches that found again a tool already found in an earlier turn of the same run=${repeatSearches} ${JSON.stringify(repeatedTools)}`);
